-- Weekly Arena 2027-W04: generated by scripts/weekly-arena.ts. Safe to rerun (skips if the title already exists).
insert into public.arenas(title, description, starts_at, ends_at, duration_minutes, status, questions)
select 'Weekly Arena 2027-W04', 'Fresh weekly set of 10 numeric questions across Algebra, Geometry, Combinatorics and Number Theory. Each question allows three submissions. New questions every week, none repeated from earlier arenas.', '2027-01-25T00:00:00.000Z', '2027-02-01T00:00:00.000Z', 60, 'published', $WKda874e2f0084$[{"id":"wk-2027-w04-01-2e22","title":"The Isosceles Trapezoid","topic":"Geometry","level":"Foundation","question":"An isosceles trapezoid has parallel sides of lengths $29$ and $17$ and each non-parallel side has length $10$. Find its area.","type":"text","correctAnswer":"184","hint":"Drop perpendiculars from the shorter base; each cuts off a right triangle with base $6$ and hypotenuse $10$.","solution":"The height is $\\sqrt{10^2-6^2}=8$, so the area is $\\tfrac12(29+17)(8)=184$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":3,"abstraction":2,"points":47,"difficulty":-0.52},{"id":"wk-2027-w04-02-c9d6","title":"Tangent and Secant","topic":"Geometry","level":"Intermediate","question":"From an external point $P$, a tangent $PT$ of length $32$ and a secant meeting the circle at $A$ and $B$ are drawn, with $PA < PB$ and $PA=16$. Find $PA + PB + PT$.","type":"text","correctAnswer":"112","hint":"Apply the power of a point: $PT^2=PA\\cdot PB$.","solution":"$PB=32^2/16=64$, so the sum is $16+64+32=112$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":3,"abstraction":3,"points":53,"difficulty":-0.28},{"id":"wk-2027-w04-03-1bbd","title":"A Blocked Lattice Path","topic":"Combinatorics","level":"Intermediate","question":"A path from $(0,0)$ to $(9,7)$ moves only one unit right or one unit up at each step. How many such paths avoid the point $(6,5)$?","type":"text","correctAnswer":"6820","hint":"Subtract the paths that pass through the forbidden point from the total.","solution":"$\\binom{16}{9}-\\binom{11}{6}\\binom{5}{3}=6820$.","answerMode":"numeric-grid","answerDigits":4,"maxAttempts":3,"estimatedSteps":4,"abstraction":3,"points":60,"difficulty":0},{"id":"wk-2027-w04-04-38e4","title":"Three Remainders","topic":"Number Theory","level":"Intermediate","question":"Find the smallest positive integer $n$ such that $n\\equiv 8 \\pmod{11}$, $n\\equiv 6 \\pmod{9}$, $n\\equiv 12 \\pmod{13}$.","type":"text","correctAnswer":"987","hint":"The moduli are pairwise coprime, so the Chinese Remainder Theorem gives a unique residue class.","solution":"Combining the congruences gives the residue class of $987$ modulo $1287$, and $987$ is its smallest positive member.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":4,"abstraction":3,"points":60,"difficulty":0},{"id":"wk-2027-w04-05-ecae","title":"Multiples of Two Numbers","topic":"Algebra","level":"Intermediate","question":"Find the sum of all positive integers not exceeding $465$ that are divisible by $11$ or by $7$ (or both).","type":"text","correctAnswer":"23793","hint":"Add the sum of multiples of each number, then subtract the multiples of their product that were counted twice.","solution":"Inclusion-exclusion over multiples of $11$, $7$ and $77$ gives $23793$.","answerMode":"numeric-grid","answerDigits":5,"maxAttempts":3,"estimatedSteps":4,"abstraction":2,"points":54,"difficulty":-0.24},{"id":"wk-2027-w04-06-a1fa","title":"Triangles From Diagonals Only","topic":"Geometry","level":"Intermediate","question":"Three vertices of a convex $15$-gon are chosen so that none of the three sides of the resulting triangle is a side of the polygon. How many such triangles are there?","type":"text","correctAnswer":"275","hint":"Count all triangles and remove those that use at least one polygon side, by inclusion-exclusion.","solution":"The count is $\\dfrac{n(n-4)(n-5)}{6}$ with $n=15$, i.e. $275$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":4,"abstraction":3,"points":60,"difficulty":0},{"id":"wk-2027-w04-07-4c25","title":"Powers of the Roots","topic":"Algebra","level":"Advanced","question":"Let $r$ and $s$ be the roots of $t^2 - 6t + 1 = 0$. Find the remainder when $r^{6} + s^{6}$ is divided by $1000$.","type":"text","correctAnswer":"202","hint":"Let $S_k=r^k+s^k$. Then $S_k=6S_{k-1}-1S_{k-2}$, with $S_0=2$, $S_1=6$.","solution":"Using $S_k=6S_{k-1}-1S_{k-2}$ from $S_0=2$, $S_1=6$ gives $S_{6}=39202$, whose remainder modulo $1000$ is $202$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":4,"abstraction":3,"points":60,"difficulty":0},{"id":"wk-2027-w04-08-037f","title":"Rearranging a Word","topic":"Combinatorics","level":"Advanced","question":"In how many distinct ways can the letters of $\\text{JJLLKKGGG}$ be rearranged so that no two identical letters are adjacent?","type":"text","correctAnswer":"1686","hint":"Count all arrangements, then use inclusion-exclusion by gluing identical letters together.","solution":"Inclusion-exclusion (confirmed by exhaustive enumeration) gives $1686$.","answerMode":"numeric-grid","answerDigits":4,"maxAttempts":3,"estimatedSteps":5,"abstraction":4,"points":73,"difficulty":0.52},{"id":"wk-2027-w04-09-1975","title":"The Last Three Digits","topic":"Number Theory","level":"Advanced","question":"Find the remainder when $3^{60}$ is divided by $1000$.","type":"text","correctAnswer":"201","hint":"Work modulo $8$ and modulo $125$ separately and combine, or use the order of the unit in $(\\mathbb Z/1000)^\\times$.","solution":"Modular exponentiation gives $3^{60}\\equiv 201 \\pmod{1000}$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":4,"abstraction":3,"points":60,"difficulty":0},{"id":"wk-2027-w04-10-4900","title":"A Floor Sum","topic":"Algebra","level":"Advanced","question":"Compute $\\displaystyle\\sum_{k=1}^{36} \\left\\lfloor \\frac{7k}{8} \\right\\rfloor$.","type":"text","correctAnswer":"566","hint":"Write $7k=8q+r$ and track how the remainder cycles with period $8$.","solution":"Evaluating each floor term and adding gives $566$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":4,"abstraction":3,"points":60,"difficulty":0}]$WKda874e2f0084$::jsonb
